// TagNode represents a #tag in the markdown AST.
type TagNode struct {
	gast.BaseInline

	// Tag name without the # prefix
	Tag []byte
}

// KindTag is the NodeKind for TagNode.
var KindTag = gast.NewNodeKind("Tag")

